package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class M2mTokenTtlSecondsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property m 2m token ttl seconds of trusted client ")
  void test_m_2m_token_ttl_seconds_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> M2mTokenTtlSecondsVO.tryFrom(null));
    Assertions.assertEquals(1, M2mTokenTtlSecondsVO.from(1).getM2mTokenTtlSeconds());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> M2mTokenTtlSecondsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", M2mTokenTtlSecondsVO.from(1).toString());
  }
}
